<?php $r = $payout_request; $labels = array('pending' => 'На рассмотрении', 'approved' => 'Одобрен', 'rejected' => 'Отклонён', 'paid' => 'Выплачен'); $sex = (int) ($r['sex'] ?? 0) === 1 ? 'Женский' : ((int) ($r['sex'] ?? 0) === 2 ? 'Мужской' : '—'); ?>
<div class="page-bar"><ul class="page-breadcrumb"><li><a href="/<?= ADM_CONTROLLER ?>/">Главная</a><i class="fa fa-circle"></i></li><li><a href="/<?= ADM_CONTROLLER ?>/creator_payouts">Запросы на выплату</a><i class="fa fa-circle"></i></li><li><span>Запрос #<?= (int) $r['id'] ?></span></li></ul></div>
<h1 class="page-title">Запрос на выплату #<?= (int) $r['id'] ?></h1>
<div class="portlet light"><div class="portlet-title"><div class="caption">Клиент #<?= (int) $r['client_id'] ?> · <?= html_escape(trim($r['name'] . ' ' . $r['surname'])) ?></div><div class="actions"><span class="label label-<?= $r['status'] === 'pending' ? 'warning' : ($r['status'] === 'approved' ? 'success' : 'danger') ?>"><?= $labels[$r['status']] ?? html_escape($r['status']) ?></span></div></div><div class="portlet-body">
